use zopro_bn254::Fr;use serde_json::json;
#[path="/home/ubuntu/src/zk-tools/zopro/crates/zopro-core/src/solver/sparse_poseidon/constants.rs"]mod constants;
fn main(){let mut out=Vec::new();for t in 2..=13{let(partial,a)=constants::parameters(t);let m=&a[8*t+partial..8*t+partial+t*t];let inv:Vec<_>=m.iter().map(|v|v.inverse().unwrap()).collect();let cauchy=(0..t).all(|i|(0..t).all(|j|inv[i*t+j]-inv[i*t]-inv[j]+inv[0]==Fr::ZERO));let hankel=(0..t).all(|i|(0..t).all(|j|i+j<t&&m[i*t+j]==m[i+j]||i+j>=t&&m[i*t+j]==m[(t-1)*t+(i+j-(t-1))]));let toeplitz=(1..t).all(|i|(1..t).all(|j|m[i*t+j]==m[(i-1)*t+j-1]));let mut rankone=true;for i in 0..t{for k in i+1..t{for j in 0..t{for l in j+1..t{if i!=j&&i!=l&&k!=j&&k!=l&&m[i*t+j]*m[k*t+l]!=m[i*t+l]*m[k*t+j]{rankone=false;}}}}}let diag_toeplitz=t==3&&(m[4]*m[4]*m[5]*m[7]==m[0]*m[1]*m[3]*m[8]);let rankone3=t==3&&(m[1]*m[5]*m[6]==m[2]*m[7]*m[3]);out.push(json!({"width":t,"inverse_entries_additively_separable":cauchy,"direct_Hankel":hankel,"direct_Toeplitz":toeplitz,"off_diagonal_all_applicable_minors_zero":rankone,"diagonal_Toeplitz3_necessary_condition":if t==3{Some(diag_toeplitz)}else{None},"diagonal_plus_rankone3_condition":if t==3{Some(rankone3)}else{None}}));}println!("{}",json!({"structural_only":true,"matrices":out,"new_SDK_requests":0,"new_timings":0,"no_claim_of_impossibility_for_other_factorizations":true}));}
